/* MiniApart V3 — phần 2: Quản lý (chu kỳ tháng, tạo hợp đồng), Người thuê, Thợ, khung, lớp nổi, bộ định tuyến. */

/* ================= QUẢN LÝ ================= */
const TOA_QL = () => T(D.ql.toaId)
const hdQl = (phong) => D.hopDong.find((h) => h.toaId === D.ql.toaId && h.phong === phong && h.tt === 'HIEU_LUC')
const GIA = { dien: 3800, nuoc: 25000, khac: 100000 }
// Hoá đơn nháp tháng 11 tính từ chỉ số thật: tiền phòng + điện + nước + dịch vụ, làm tròn lên nghìn (khớp hoá đơn tháng 10 của phòng 101: 3.790.000 ₫).
const nhapT11 = () => D.ql.chiSo.map((c) => { const h = hdQl(c.phong), dien = (c.dien[1] - c.dien[0]) * GIA.dien, nuoc = (c.nuoc[1] - c.nuoc[0]) * GIA.nuoc, daGui = hdThang(11, D.ql.toaId).find((x) => x.phong === c.phong)
  return { phong: c.phong, nguoi: h?.nguoi, hd: h, tienPhong: h?.gia || 0, dien, nuoc, khac: GIA.khac, tong: daGui ? daGui.tong : Math.ceil(((h?.gia || 0) + dien + nuoc + GIA.khac) / 1000) * 1000, daGui } })
const thieuCt = () => [...new Set(D.ql.congTo.thieu.map((x) => x.phong))]
const railThang = (b) => { const ct = D.ql.congTo, nhap = nhapT11(), cho = nhap.filter((x) => !x.daGui)
  const ds = [['Ghi chỉ số', `${ct.daGhi}/${ct.tong} công tơ · thiếu ${ct.tong - ct.daGhi}`], ['Khoá chỉ số', 'sau khi ghi đủ'], ['Gửi hoá đơn', `${cho.length} nháp · ${nhap.length - cho.length} đã gửi`], ['Thu tiền', `đã thu ${nhap.filter((x) => x.daGui).length}/${nhap.length} phòng`]]
  return `<nav class="buoc" aria-label="Các bước của tháng 11">${ds.map(([t, p], i) => `<a href="${V(`thang/${i + 1}`)}" class="${i + 1 === b ? 'on' : ''}" ${i + 1 === b ? 'aria-current="step"' : ''}><span class="n">${i + 1}</span><span class="gian"><span class="m" style="display:block">${t}</span><span class="s cat" style="display:block">${p}</span></span></a>`).join('')}</nav>` }

M['ql/hom-nay'] = () => {
  const t = TOA_QL(), no = noTrong(), sc = D.suCo.filter((s) => s.toaId === t.id), hh = D.hopDong.filter((h) => h.toaId === t.id && h.sapHet && h.tt === 'HIEU_LUC'), ck = D.hopDong.filter((h) => h.toaId === t.id && h.tt === 'CHO_KY'), thieu = thieuCt()
  const viec = [['no', `${no.length} người nợ quá hạn, ${so(tong(no, (n) => n.tong))} ₫`, `Nhiều nhất: ${no[0].ten}, phòng ${no[0].phong}, ${so(no[0].tong)} ₫`, 'Thu tiền', V('tien')],
    ...sc.filter((s) => s.tt === 'MOI_TIEP_NHAN' || s.tt === 'DA_TIEP_NHAN').map((s) => [s.khan ? 'no' : 'canh', `${s.hangMuc} phòng ${s.phong}${s.khan ? ' (khẩn)' : ''}`, `${TT_SC[s.tt][1]} · ${s.moTa}`, 'Giao thợ', V(`su-co/${s.id}`)]),
    ...hh.map((h) => ['canh', `Hợp đồng phòng ${h.phong} hết hạn sau ${h.con} ngày`, `${h.nguoi} · đến ${ngay(h.kt)}`, 'Gia hạn', V(`hop-dong/${h.id}`)]), ...ck.map((h) => ['', `Hợp đồng phòng ${h.phong} chờ ký`, h.nguoi, 'Mở', V(`hop-dong/${h.id}`)]),
    ['', 'Bình chữa cháy quá hạn kiểm định', `Hạn ${ngay(t.pccc.thietBi[0].han)} · ${t.pccc.thietBi[0].viTri}`, 'Xem', V('pccc')]]
  return { tieuDe: 'Hôm nay', chinh: 1, html: dauTrang('Hôm nay', `Thứ Năm, ${ngay(D.ngay)} · ${t.ten}`, `<a class="nut" href="${mo('tb')}">${ic('chuong')}Thông báo <b class="so">${D.ql.thongBao.length}</b></a><a class="nut chinh" href="${V('thang/1')}">Ghi ${D.ql.congTo.tong - D.ql.congTo.daGhi} công tơ còn thiếu</a>`) +
    `<div class="bao no">${ic('canh')}<span><b>Tháng 11 đang trễ:</b> kỳ đóng ngày ${ngay(t.ky11.kt)} nhưng còn ${D.ql.congTo.tong - D.ql.congTo.daGhi} công tơ chưa ghi (phòng ${thieu.join(', ')}), nên chưa gửi được hoá đơn.</span></div>${railThang(1)}
    <div class="luoi"><div class="c8 cot">${the('Việc cần làm', `<div>${viec.map(([l, a, b, n, h]) => `<div class="dong"><div class="gian"><div class="m">${l ? `<i class="cham ${l}"></i>` : ''}${esc(a)}</div><div class="s">${esc(b)}</div></div><a class="nut" href="${h}">${n}</a></div>`).join('')}</div>`, '', `${viec.length} việc`)}</div>
      <div class="c4 cot">${the('Lịch xem phòng', `<div>${D.ql.lichHen.map((x) => `<div class="dong"><div class="gian"><div class="m">${x.gio.slice(8, 10)}/${x.gio.slice(5, 7)} · ${x.gio.slice(11)} · phòng ${x.phong}</div><div class="s">${esc(x.ten)} · ${sdt(x.sdt)}</div></div>${x.tt === 'CHO_XAC_NHAN' ? `<a class="nut" href="#" data-toast="Bản xem thử: đã xác nhận lịch">Xác nhận</a>` : cham('ok', 'Đã hẹn')}</div>`).join('')}</div>`, `<a class="nut chu" href="${V('lich-xem')}">Tất cả</a>`)}</div></div>` }
}

M['ql/thang/:id'] = M['chu/thang/:id'] = () => {
  const b = +(P.ts[0] || 1), t = TOA_QL(), ct = D.ql.congTo, thieu = thieuCt(), nhap = nhapT11(), cho = nhap.filter((x) => !x.daGui), tongDien = tong(D.ql.chiSo, (c) => c.dien[1] - c.dien[0]), tongNuoc = tong(D.ql.chiSo, (c) => c.nuoc[1] - c.nuoc[0])
  const minhHoa = `<div class="bao xl">${ic('gio')}<span>Bản vẽ này cho thấy bước ${b} <b>sau khi các bước trước đã xong</b>. Dữ liệu thật hôm nay còn ở bước 1.</span><span class="mau">minh hoạ</span></div>`
  let than, nut
  if (b === 1) {
    const dong = (so_, c) => { const h = hdQl(so_), p = t.phong.find((x) => x.so === so_), tang = c ? pt(c.dien[1] - c.dien[0], c.tbDien) - 100 : 0
      return `<tr><td class="m">${so_}</td><td>${h ? esc(h.nguoi) : `<span class="c-phu">${p.tt === 'TRONG' ? 'Phòng trống' : 'Đang sửa'}</span>`}</td><td class="r so c-phu">${c ? c.dien[0] : '—'}</td><td class="r"><input class="so-o ${c ? '' : 'thieu'}" inputmode="numeric" aria-label="Điện mới phòng ${so_}" value="${c ? c.dien[1] : ''}" placeholder="chưa ghi"></td><td class="r so">${c ? c.dien[1] - c.dien[0] : ''}</td>
        <td class="r so c-phu">${c ? c.nuoc[0] : '—'}</td><td class="r"><input class="so-o ${c ? '' : 'thieu'}" inputmode="numeric" aria-label="Nước mới phòng ${so_}" value="${c ? c.nuoc[1] : ''}" placeholder="chưa ghi"></td><td class="r so">${c ? c.nuoc[1] - c.nuoc[0] : ''}</td><td>${c ? (tang > 50 ? nhan('canh', `điện tăng ${tang}%`) : cham('ok', 'Đã ghi')) : nhan('no', 'Thiếu 2 công tơ')}</td></tr>` }
    than = the('Ghi chỉ số tháng 11', bang([['Phòng'], ['Người thuê'], ['Điện cũ', 'r'], ['Điện mới', 'r'], ['Dùng kWh', 'r'], ['Nước cũ', 'r'], ['Nước mới', 'r'], ['Dùng m³', 'r'], ['']], [...thieu.map((s) => dong(s)), ...D.ql.chiSo.map((c) => dong(c.phong, c))],
      { tongHang: `<tr class="tong"><td colspan="4">Cộng ${D.ql.chiSo.length} phòng đã ghi</td><td class="r so">${so(tongDien)}</td><td colspan="2"></td><td class="r so">${so(tongNuoc)}</td><td></td></tr>` }),
      `<span class="s"><kbd>Tab</kbd> sang ô kế · <kbd>Enter</kbd> xuống phòng dưới</span>`, `đã ghi ${ct.daGhi}/${ct.tong} công tơ · phòng thiếu xếp lên đầu`)
    nut = `<a class="nut chinh" href="#" data-toast="Bản xem thử: đã lưu chỉ số">Lưu chỉ số</a>`
  } else if (b === 2) {
    than = minhHoa + `<div class="luoi"><div class="c8 cot">${the('Kiểm lại trước khi khoá', `<div>${[['ok', `Đã ghi đủ ${ct.tong}/${ct.tong} công tơ`, 'Không còn phòng nào thiếu chỉ số.'], ['ok', 'Không có chỉ số nào nhỏ hơn tháng trước', 'Chỉ số mới luôn lớn hơn hoặc bằng chỉ số cũ.'], ['ok', 'Không phòng nào tăng quá 50% so với trung bình 3 tháng', 'Phòng tăng bất thường sẽ hiện ở đây để gọi hỏi trước khi tính tiền.']].map(([l, a, b2]) => `<div class="dong"><span class="c-ok">${ic('xong')}</span><div class="gian"><div class="m">${a}</div><div class="s">${b2}</div></div></div>`).join('')}</div>`)}
        ${the('Tổng dùng tháng 11', bang([['Dịch vụ'], ['Tháng 11', 'r'], ['Tháng 10', 'r'], ['Chênh', 'r']], [`<tr><td>${ic('dien')} Điện</td><td class="r so b">${so(tongDien)} kWh</td><td class="r so">${so(tong(D.ql.chiSo, (c) => c.tbDien))} kWh</td><td class="r so">${((d) => (d > 0 ? '+' : d < 0 ? '−' : '') + Math.abs(d))(tongDien - tong(D.ql.chiSo, (c) => c.tbDien))}</td></tr>`, `<tr><td>${ic('nuoc')} Nước</td><td class="r so b">${so(tongNuoc)} m³</td><td class="r so">${so(tongNuoc)} m³</td><td class="r so">0</td></tr>`]))}</div>
      <div class="c4 cot">${the('Khoá xong thì sao', `<div class="th cot"><p>Chỉ số tháng 11 <b>không sửa được nữa</b>. Sai thì phải lập hoá đơn điều chỉnh.</p><p class="s">Sau khi khoá, hệ thống tính sẵn ${nhap.length} hoá đơn nháp để anh/chị xem lại ở bước 3.</p></div>`)}</div></div>`
    nut = `<a class="nut chinh" href="${mo('xn', { kieu: 'khoa' })}">${ic('khoa')}Khoá chỉ số tháng 11</a>`
  } else if (b === 3) {
    than = minhHoa + the('Hoá đơn nháp tháng 11', bang([[''], ['Phòng'], ['Người thuê'], ['Tiền phòng', 'r'], ['Điện', 'r'], ['Nước', 'r'], ['Dịch vụ', 'r'], ['Tổng', 'r'], ['']], nhap.map((x) => `<tr><td style="width:40px"><label class="chk"><input type="checkbox" ${x.daGui ? 'disabled' : 'checked'} aria-label="Chọn phòng ${x.phong}"></label></td><td class="m">${x.phong}</td><td>${esc(x.nguoi)}</td><td class="r">${tien(x.tienPhong)}</td><td class="r">${tien(x.dien)}</td><td class="r">${tien(x.nuoc)}</td><td class="r">${tien(x.khac)}</td><td class="r b">${tien(x.tong)}</td>
        <td>${x.daGui ? cham('ok', 'Đã gửi, đã trả') : x.hd?.sapHet ? nhan('canh', `HĐ hết hạn ${ngayNgan(x.hd.kt)}`) : ''}</td></tr>`), { tongHang: `<tr class="tong"><td></td><td colspan="2">Sẽ gửi ${cho.length} hoá đơn</td><td class="r">${tien(tong(cho, (x) => x.tienPhong))}</td><td class="r">${tien(tong(cho, (x) => x.dien))}</td><td class="r">${tien(tong(cho, (x) => x.nuoc))}</td><td class="r">${tien(tong(cho, (x) => x.khac))}</td><td class="r">${tien(tong(cho, (x) => x.tong))}</td><td></td></tr>` }),
      `<a class="nut" href="#" data-toast="Bản xem thử: mở bản xem trước hoá đơn phòng 102">Xem thử một hoá đơn</a>`, `hạn trả ${t.hanTt} ngày sau khi gửi · người thuê nhận tin trên điện thoại`)
    nut = `<a class="nut chinh" href="${mo('xn', { kieu: 'gui' })}">Gửi ${cho.length} hoá đơn · ${so(tong(cho, (x) => x.tong))} ₫</a>`
  } else {
    const daThu = nhap.filter((x) => x.daGui), no = noTrong()
    than = minhHoa + `<section class="the dai"><div><div class="s">Đã thu tháng 11</div><div class="vua">${so(tong(daThu, (x) => x.tong))}<span class="d">₫</span></div><div class="s">${daThu.length}/${nhap.length} phòng</div></div><div><div class="s">Chưa trả</div><div class="vua">${so(tong(cho, (x) => x.tong))}<span class="d">₫</span></div><div class="s">${cho.length} phòng · hạn ${ngay('2026-12-03')}</div></div>
      <div><div class="s">Nợ cũ các tháng trước</div><div class="vua c-no">${so(tong(no, (n) => n.tong))}<span class="d">₫</span></div><div class="s"><a class="c-xl" href="${V('tien')}">${no.length} người · mở danh sách nợ</a></div></div></section>` +
      the('Hoá đơn tháng 11', bang([['Phòng'], ['Người thuê'], ['Phải trả', 'r'], ['Tình trạng'], ['', 'r']], nhap.map((x) => `<tr><td class="m">${x.phong}</td><td>${esc(x.nguoi)}</td><td class="r b">${tien(x.tong)}</td><td>${x.daGui ? cham('ok', 'Đã trả đủ') : cham('', 'Chưa trả, còn 7 ngày')}</td><td class="r">${x.daGui ? '' : `<span class="hang" style="justify-content:flex-end;gap:8px">${nutGoi(D.nguoi[x.hd.nguoiId]?.sdt)}<a class="nut" href="${mo('thu', { id: x.hd.nguoiId })}">Ghi thu</a></span>`}</td></tr>`)),
        `<a class="nut" href="${mo('nhac', { id: 'nhieu' })}">${ic('tin')}Nhắc ${cho.length} người chưa trả</a>`)
    nut = `<a class="nut chinh" href="${mo('thu', { id: cho[0].hd.nguoiId })}">${ic('them')}Ghi thu tiền</a>`
  }
  return { tieuDe: `Tháng 11 · bước ${b}`, chinh: 1, html: dauTrang('Tháng 11/2026', `${t.ten} · kỳ ${ngay(t.ky11.bd)} – ${ngay(t.ky11.kt)}`, `<label class="o an-m" style="grid-auto-flow:column;align-items:center;gap:8px"><span class="s" style="font-weight:400">Tháng</span><select style="width:190px"><option>11/2026 (đang làm)</option><option>10/2026</option><option>9/2026</option></select></label>${nut}`) + railThang(b) + than }
}

M['ql/hop-dong/moi'] = M['chu/hop-dong/moi'] = () => {
  const t = P.vai === 'ql' ? TOA_QL() : T(toaChon() || 3), trong = t.phong.filter((p) => p.tt === 'TRONG'), p = trong[0], dv = D.hopDong.find((h) => h.toaId === t.id).dv
  const html = `<nav class="vet"><a href="${V('hop-dong')}">Hợp đồng</a>${ic('phai')}<span>Tạo hợp đồng</span></nav>` + dauTrang('Tạo hợp đồng', `${t.ten} · một trang, điền từ trên xuống`, `<a class="nut an-m" href="${V('hop-dong')}">Huỷ</a><a class="nut chinh" href="#" data-toast="Bản xem thử: đã tạo hợp đồng, chờ hai bên ký">Tạo hợp đồng</a>`) +
    `<div class="luoi"><div class="c8 cot">
      ${the('1. Phòng và người thuê', `<div class="th luoi" style="gap:16px"><label class="o c6"><span>Phòng</span><select>${trong.map((x) => `<option>${x.so} · ${x.dt} m² · ${so(x.gia)} ₫/tháng</option>`).join('')}</select><small>Chỉ hiện ${trong.length} phòng đang trống.</small></label>
        <label class="o c6"><span>Người thuê</span><input value="" placeholder="Gõ tên hoặc số điện thoại"><small>Chưa có trong danh sách? Gõ số điện thoại rồi chọn "Thêm người mới".</small></label>
        <label class="o c6"><span>Số CCCD</span><input inputmode="numeric" placeholder="12 số"></label><label class="o c6"><span>Số người ở</span><input inputmode="numeric" value="2"><small>Phòng này ở tối đa 3 người.</small></label></div>`)}
      ${the('2. Thời hạn và tiền', `<div class="th luoi" style="gap:16px"><label class="o c4"><span>Ngày bắt đầu</span><input value="01/12/2026"></label><label class="o c4"><span>Thuê bao lâu</span><select><option>12 tháng</option><option>6 tháng</option><option>24 tháng</option></select></label><label class="o c4"><span>Ngày kết thúc</span><input value="30/11/2027" disabled><small>Tự tính.</small></label>
        <label class="o c4"><span>Giá thuê mỗi tháng</span><input class="so r" inputmode="numeric" value="${so(p.gia)}"><small>Giá niêm yết của phòng.</small></label><label class="o c4"><span>Tiền cọc</span><input class="so r" inputmode="numeric" value="${so(p.gia * 2)}"><small>Mặc định 2 tháng tiền phòng.</small></label><label class="o c4"><span>Báo trước khi trả phòng</span><select><option>30 ngày</option><option>45 ngày</option></select></label></div>`)}
      ${the('3. Dịch vụ tính hàng tháng', bang([[''], ['Dịch vụ'], ['Cách tính'], ['Đơn giá', 'r']], dv.map((d) => `<tr><td style="width:40px"><label class="chk"><input type="checkbox" checked aria-label="${d.ten}"></label></td><td class="m">${d.ten}</td><td class="c-phu">${/Điện|Nước/.test(d.ten) ? 'theo công tơ' : /Vệ sinh/.test(d.ten) ? 'theo số người' : 'cố định mỗi tháng'}</td><td class="r">${d.gia ? tien(d.gia) : 'Miễn phí'}</td></tr>`)), '', 'lấy theo bảng giá của toà, đổi riêng cho hợp đồng này nếu cần')}</div>
    <div class="c4 cot" style="position:sticky;top:16px">${the('Thu khi ký', `<div class="th">${kv([['Tiền cọc', tien(p.gia * 2)], ['Tiền phòng tháng đầu', tien(p.gia)], ['<b>Tổng thu khi ký</b>', `<b>${tien(p.gia * 3)}</b>`]])}<p class="s" style="margin-top:10px">Điện nước tính từ chỉ số bàn giao, vào hoá đơn tháng 12.</p></div>`)}
      ${the('Còn thiếu', `<div><div class="dong"><span class="c-no">${ic('canh')}</span><div class="gian"><div class="m">Chưa chọn người thuê</div></div></div><div class="dong"><span class="c-no">${ic('canh')}</span><div class="gian"><div class="m">Chưa có số CCCD</div></div></div><div class="dong"><span class="c-ok">${ic('xong')}</span><div class="gian"><div>Phòng, thời hạn, giá, dịch vụ đã đủ</div></div></div></div>`)}</div></div>`
  return { tieuDe: 'Tạo hợp đồng', chinh: 1, html }
}

/* ================= NGƯỜI THUÊ (điện thoại) ================= */
const KH = () => D.no.find((n) => n.id === 1), HDKH = () => D.hopDong.find((h) => h.nguoiId === 1 && h.tt === 'HIEU_LUC')
const NAV_DT = { kh: [['can-tra', 'Tiền nhà', 'vi'], ['bao-hong', 'Báo hỏng', 'sua'], ['hop-dong', 'Phòng tôi', 'home'], ['lich-su', 'Lịch sử', 'gio']], tho: [['viec', 'Việc', 'sua'], ['tien-cong', 'Tiền công', 'vi']] }
function dienThoai(m) {
  const nav = NAV_DT[P.vai].map(([d, n, i]) => `<a href="${V(d)}" class="${P.duong.split('/')[0] === d || (m.nav === d) ? 'on' : ''}">${ic(i)}<span>${n}</span></a>`).join('')
  return `<div class="san"><div class="dt d-thoang"><header class="dt-dau">${m.lui ? `<a class="nut vuong chu" style="color:var(--muc);margin-left:-10px" href="${m.lui}" aria-label="Quay lại">${ic('lui')}</a>` : ''}<div class="gian"><h1 style="font:inherit">${m.tieuDe}</h1>${m.phu ? `<div class="s" style="font-weight:400">${m.phu}</div>` : ''}</div>
    ${m.lui ? '' : `<a class="nut vuong chu" style="color:var(--muc);position:relative" href="${mo('tb')}" aria-label="Thông báo">${ic('chuong')}${m.tb ? `<span style="position:absolute;top:6px;right:6px;width:10px;height:10px;border-radius:50%;background:var(--no);border:2px solid #fff"></span>` : ''}</a>`}</header>
    <main class="dt-than">${m.html}</main>${m.chan ? `<div class="dt-chan ${m.lui ? 'day' : ''}">${m.chan}</div>` : ''}${m.lui ? '' : `<nav class="dt-nav" aria-label="Điều hướng">${nav}</nav>`}</div></div>`
}
const QR = (() => { let s = 7, o = ''; const r = () => ((s = (s * 16807) % 2147483647) % 100) / 100; const mat = (x, y) => `<rect x="${x}" y="${y}" width="7" height="7"/><rect x="${x + 1}" y="${y + 1}" width="5" height="5" fill="#fff"/><rect x="${x + 2}" y="${y + 2}" width="3" height="3"/>`
  for (let y = 0; y < 29; y++) for (let x = 0; x < 29; x++) { const goc = (x < 8 && y < 8) || (x > 20 && y < 8) || (x < 8 && y > 20); if (!goc && r() > 0.52) o += `<rect x="${x}" y="${y}" width="1" height="1"/>` }
  return `<svg class="qr" viewBox="-2 -2 33 33" role="img" aria-label="Mã QR chuyển khoản (minh hoạ)" shape-rendering="crispEdges"><rect x="-2" y="-2" width="33" height="33" fill="#fff"/><g fill="#14181d">${o}${mat(0, 0)}${mat(22, 0)}${mat(0, 22)}</g></svg>` })()

