function toast(chu) { const t = document.getElementById('toast'); t.innerHTML = `${ic('xong')}<span>${esc(chu)}</span>`; t.hidden = false; clearTimeout(toast.h); toast.h = setTimeout(() => (t.hidden = true), 6000) }
